<main><section class="v700-account-hero"><div class="v700-shell"><span class="v700-kicker">LIVE RIDE REQUEST</span><h1>Where do you need to go?</h1><p>Submit a ride request. Tenant transport staff can assign an operator, vehicle and driver.</p></div></section><section class="v700-section soft"><div class="v700-shell" style="max-width:820px"><?php if($flash):?><div class="v700-alert success"><?=e($flash)?></div><?php endif;?><?php if($err):?><div class="v700-alert error"><?=e($err)?></div><?php endif;?><form method="post" class="v700-panel v700-form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><label>Service<select name="service_type"><option value="ride">Ride</option><option value="rickshaw">Rickshaw</option><option value="taxi">Taxi</option><option value="bike">Bike</option></select></label><label>Pickup Address<textarea name="pickup_address" required></textarea></label><label>Destination<textarea name="destination_address" required></textarea></label><div class="two"><label>Scheduled Time (optional)<input type="datetime-local" name="scheduled_at"></label><label>Notes<input name="notes" placeholder="Landmark, gate, instructions"></label></div><button class="v700-btn primary">Request Ride</button></form></div></section></main><?php v700_public_footer(); ?>
